// Browser contract test only. Uses system Chromium and Node's built-in CDP WebSocket.
// No product JavaScript or third-party assets are generated by this test.
import { createServer } from 'node:http';
import { readFile, writeFile, mkdtemp, rm } from 'node:fs/promises';
import { resolve, join, extname } from 'node:path';
import { tmpdir } from 'node:os';
import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';

const root = resolve('dist/c0host');
const work = await mkdtemp(join(tmpdir(), 'c0pdf-smoke-'));
const checks = [];
const errors = [];
const server = createServer(async (req, res) => {
  try {
    const path = resolve(root, '.' + new URL(req.url, 'http://localhost').pathname);
    if (path !== root && !path.startsWith(root + '/')) { res.writeHead(403).end(); return; }
    let file = path === root || req.url === '/' ? join(root, 'index.html') : path;
    if (process.env.C0PDF_CLOCK_PROBE_DIR && req.url.startsWith('/__clock_probe/') && !req.url.includes('..')) {
      file = join(process.env.C0PDF_CLOCK_PROBE_DIR, req.url.slice('/__clock_probe/'.length));
    }
    const mime = { '.wasm': 'application/wasm', '.js': 'text/javascript', '.html': 'text/html' };
    res.setHeader('Content-Type', mime[extname(file)] || 'application/octet-stream');
    res.end(await readFile(file));
  } catch { res.writeHead(404).end(); }
});
await new Promise(done => server.listen(0, '127.0.0.1', done));
const url = `http://127.0.0.1:${server.address().port}/`;
const browser = spawn('/usr/bin/chromium', ['--headless', '--no-sandbox', '--disable-dev-shm-usage',
  '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader', '--remote-debugging-port=0',
  `--user-data-dir=${work}/profile`, '--window-size=1280,900', 'about:blank'], {stdio:['ignore','ignore','pipe']});
let socket;
try {
  const endpoint = await new Promise((done, reject) => {
    let log = '';
    const timer = setTimeout(() => reject(new Error('Chromium startup timeout')), 30000);
    browser.stderr.on('data', data => {
      log += data;
      const match = log.match(/DevTools listening on (ws:\/\/[^\s]+)/);
      if (match) {clearTimeout(timer); done(match[1]);}
    });
    browser.on('exit', code => reject(new Error(`Chromium exited ${code}`)));
  });
  const port = new URL(endpoint).port;
  const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  socket = new WebSocket(targets.find(target => target.type === 'page').webSocketDebuggerUrl);
  await new Promise((done, reject) => { socket.onopen = done; socket.onerror = reject; });
  let sequence = 0;
  const pending = new Map();
  const events = new Map();
  socket.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.id) {
      const entry = pending.get(message.id);
      if (entry) {pending.delete(message.id); clearTimeout(entry.timer); message.error ? entry.reject(message.error) : entry.done(message.result);}
    } else {
      if (message.method === 'Runtime.exceptionThrown') { errors.push(message.params.exceptionDetails.text); }
      for (const callback of events.get(message.method) || []) callback(message.params);
    }
  };
  const send = (method, params = {}) => new Promise((done, reject) => {
    const id = ++sequence;
    const timer = setTimeout(() => {pending.delete(id); reject(new Error(`${method} timeout`));}, 30000);
    pending.set(id, {done, reject, timer}); socket.send(JSON.stringify({id, method, params}));
  });
  const evaluate = async expression => {
    const value = await send('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true, userGesture:true});
    if (value.exceptionDetails) throw new Error(JSON.stringify(value.exceptionDetails));
    return value.result.value;
  };
  const request = (method, params = {}) => evaluate(`window.__c0hostRequest(${JSON.stringify(JSON.stringify({method, params}))}).then(JSON.parse)`);
  const ok = async (method, params = {}) => {
    const reply = await request(method, params);
    if (!reply.ok) {
      const debug = {state:await request('c0.inspect'), ui:await request('ui.state'), widgets:await request('ui.inspect', {limit:300})};
      await writeFile('/tmp/c0pdf-lane/browser-debug.json', JSON.stringify(debug,null,2));
      const shot = await send('Page.captureScreenshot', {format:'png'});
      await writeFile('/tmp/c0pdf-lane/browser-failure.png', Buffer.from(shot.data,'base64'));
    }
    assert.equal(reply.ok, true, `${method}: ${JSON.stringify(reply)}`);
    checks.push(method); return reply.result;
  };
  await send('Runtime.enable'); await send('Page.enable');
  await send('Page.navigate', {url});
  const until = Date.now() + 90000;
  while (!(await evaluate('typeof window.__c0hostRequest === "function"'))) {
    if (Date.now() > until) throw new Error('page bridge did not start');
    await new Promise(done => setTimeout(done, 100));
  }
  const initial = await ok('c0.inspect');
  if (process.env.C0PDF_CLOCK_PROBE_DIR) {
    const probe = await evaluate(`(async () => {
      const clock = await import('/__clock_probe/clock_probe.js');
      await clock.default({module_or_path:'/__clock_probe/clock_probe_bg.wasm'});
      let previousTrapped = false;
      try {clock.previous_system_time();} catch (error) {previousTrapped = error instanceof WebAssembly.RuntimeError;}
      return {previousTrapped, seconds:clock.fixed_system_time(), now:Date.now()/1000};
    })()`);
    assert.equal(probe.previousTrapped, true);
    assert(Math.abs(probe.seconds - probe.now) < 2);
    checks.push('previous SystemTime traps; actual replacement clock succeeds');
  }
  const commandCount = (await ok('ui.commands')).commands.length;
  assert.equal(initial.pageCount, 0); assert.deepEqual(initial.documents, []);
  assert.equal(initial.panes.chrome.start_screen, false);
  assert.equal(initial.panes.chrome.community_links, false);
  checks.push('empty startup');
  // Generate an actual synthetic PDF, with two pages, a bookmark, annotation and text field.
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R /Outlines 6 0 R /AcroForm << /Fields [9 0 R] >> >>',
    '<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 /MediaBox [0 0 200 300] >>',
    '<< /Type /Page /Parent 2 0 R /Resources << >> /Annots [8 0 R 9 0 R] >>',
    '<< /Type /Page /Parent 2 0 R /Resources << >> >>', '<< >>',
    '<< /Type /Outlines /First 7 0 R /Last 7 0 R /Count 1 >>',
    '<< /Title (Second page) /Parent 6 0 R /Dest [4 0 R /Fit] >>',
    '<< /Type /Annot /Subtype /Text /P 3 0 R /Rect [10 250 30 270] /Contents (Synthetic note) >>',
    '<< /Type /Annot /Subtype /Widget /FT /Tx /T (Name) /V (Guest) /P 3 0 R /Rect [40 220 160 250] >>',
  ];
  let pdf = '%PDF-1.7\n'; const offsets = [0];
  objects.forEach((object, index) => {offsets.push(Buffer.byteLength(pdf)); pdf += `${index+1} 0 obj\n${object}\nendobj\n`;});
  const xref = Buffer.byteLength(pdf);
  pdf += `xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;
  for (const offset of offsets.slice(1)) pdf += `${String(offset).padStart(10, '0')} 00000 n \n`;
  pdf += `trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  const fixture = join(work, 'synthetic.pdf'); await writeFile(fixture, pdf);
  const bytes = (await readFile(fixture)).toString('base64');
  await ok('c0.openFile', {name:'synthetic.pdf', bytes});
  const opened = await ok('c0.inspect');
  assert.equal(opened.pageCount, 2); assert.equal(opened.formFieldCount, 1);
  assert(opened.annotationCount >= 1); assert.equal(opened.outline[0].title, 'Second page');
  await ok('c0.goTo', {outline:0}); assert.equal((await ok('c0.inspect')).currentPage, 1);
  await ok('c0.goTo', {page:0});
  const exported = await ok('c0.documentBytes');
  assert.equal(exported.format, 'pdf'); assert(Buffer.from(exported.bytes, 'base64').subarray(0,5).equals(Buffer.from('%PDF-')));
  assert.equal((await ok('c0.inspect')).dirty, false);
  await ok('c0.openFile', {name:'roundtrip.pdf', bytes:exported.bytes});
  assert.equal((await ok('c0.inspect')).pageCount, 2);
  let chooser;
  events.set('Page.fileChooserOpened', [event => {chooser = event;}]);
  await send('Page.setInterceptFileChooserDialog', {enabled:true});
  await ok('ui.command', {id:'file.open'});
  assert.equal((await ok('c0.inspect')).fileDialog, true);
  assert.equal((await ok('c0.cancelFileDialog')).cancelled, true);
  for (let attempt = 0; !chooser && attempt < 20; attempt++) await new Promise(done => setTimeout(done, 20));
  assert(chooser?.backendNodeId, 'the real browser Open chooser must be intercepted');
  await send('DOM.setFileInputFiles', {backendNodeId:chooser.backendNodeId, files:[fixture]});
  await new Promise(done => setTimeout(done, 50));
  assert.equal((await ok('c0.inspect')).name, 'roundtrip.pdf');
  await send('Page.setInterceptFileChooserDialog', {enabled:false});
  checks.push('cancelled browser chooser ignores its late file');
  const palette = await ok('c0.set', {themeTokens:{pasteboard:'#263238',accent:'#ff8a65',invalid:'#ffffff',text:3},panels:{tools_panel:false}});
  assert.deepEqual(palette.unknown, ['themeTokens.invalid']); assert.deepEqual(palette.invalid, ['themeTokens.text']);
  await ok('ui.command', {id:'view.theme.dark'}); assert.equal((await ok('c0.inspect')).theme, 'dark');
  // Hold animation-frame presentation. A request must still answer via an inline logic pass.
  await evaluate('window.__c0raf = window.requestAnimationFrame; window.__c0frames = []; window.requestAnimationFrame = callback => {window.__c0frames.push(callback); return -1;}');
  assert.equal((await ok('c0.inspect')).pageCount, 2);
  await ok('c0.goTo', {page:1}); await ok('c0.documentBytes');
  checks.push('requests while animation frames disabled');
  for (const [key, strip] of [['toolbar_double', {columns:2, floating:false}], ['toolbar_floating', {columns:1, floating:true}]]) {
    const set = await ok('c0.set', {panels:{[key]:true}});
    assert.deepEqual(set.applied, [`panels.${key}`]);
    const panes = (await ok('c0.inspect')).panes;
    assert.equal(panes.chrome[key], true); assert.equal(panes.strip.columns, strip.columns); assert.equal(panes.strip.floating, strip.floating);
    await ok('c0.set', {panels:{[key]:false}}); assert.equal((await ok('c0.inspect')).panes.chrome[key], false);
  }
  await ok('c0.set', {panels:{toolbar:false}}); assert.equal((await ok('c0.inspect')).panes.chrome.toolbar, false);
  await ok('c0.set', {panels:{toolbar:true}});
  await ok('c0.set', {panels:{right_dock_collapsed:true}}); assert.equal((await ok('c0.inspect')).panes.chrome.right_dock_collapsed, true);
  await ok('c0.set', {panels:{right_dock_collapsed:false}}); assert.equal((await ok('c0.inspect')).panes.chrome.right_dock_collapsed, false);
  assert.deepEqual((await ok('c0.set', {panels:{toolbar_triple:true}})).unknown, ['panels.toolbar_triple']);
  checks.push('tool-strip modes and right-dock fold set and read back');
  const rendered = await ok('ui.render', {page:1, scale:0.5});
  const png = Buffer.from(rendered.png_base64, 'base64');
  assert.equal(png.subarray(1, 4).toString(), 'PNG'); assert.equal(png.readUInt32BE(16), rendered.width); assert.equal(rendered.page, 1);
  assert.equal((await request('ui.render', {page:99})).ok, false);
  checks.push('frameless ui.render while animation frames disabled');
  assert.equal((await request('c0.goTo', {page:-1})).ok, false);
  assert.equal((await request('c0.openFile', {name:'bad.pdf',bytes:'!'})).ok, false);
  assert.equal((await evaluate('window.__c0hostRequest("oops").then(JSON.parse)')).ok, false);
  await ok('c0.cancelFileDialog');
  await ok('c0.newDocument'); assert.equal((await ok('c0.inspect')).dirty, true);
  assert.equal((await ok('c0.openFile', {name:'pending.pdf',bytes})).pending, true);
  await ok('ui.inspect', {query:'Cancel'});
  await ok('ui.click', {label:'Cancel'});
  assert.equal((await ok('c0.inspect')).name, 'Untitled.pdf');
  assert.equal((await ok('c0.openFile', {name:'pending.pdf',bytes})).pending, true);
  await ok('ui.inspect', {query:"Don't save"});
  await ok('ui.click', {label:"Don't save"});
  assert.equal((await ok('c0.inspect')).name, 'pending.pdf');
  checks.push('actual Save Changes Cancel and Discard');
  await ok('ui.command', {id:'page.rotate'});
  const dated = Buffer.from((await ok('c0.documentBytes')).bytes, 'base64').toString('latin1');
  assert.match(dated, new RegExp('/ModDate\\s*\\(D:' + new Date().getUTCFullYear()));
  checks.push('browser UTC wall clock writes current ModDate');
  await ok('c0.goTo', {page:0});
  await evaluate('window.requestAnimationFrame = window.__c0raf; for (const callback of window.__c0frames.splice(0)) window.requestAnimationFrame(callback)');
  await ok('c0.set', {panels:{tools_panel:false}});
  await new Promise(done => setTimeout(done, 300));
  assert.deepEqual((await ok('ui.state')).active.page_errors, []);
  const screenshot = await send('Page.captureScreenshot', {format:'png'});
  const screenshotPath = process.env.C0PDF_SCREENSHOT || '/tmp/c0pdf-lane/browser.png';
  await writeFile(screenshotPath, Buffer.from(screenshot.data, 'base64'));
  assert.deepEqual(errors, []);
  const state = await ok('c0.inspect');
  console.log(JSON.stringify({passed:checks.length, checks, commandCount, runtimeErrors:errors, screenshot:screenshotPath, state}, null, 2));
} finally {
  socket?.close(); server.close();
  if (browser.exitCode === null) {
    const exited = new Promise(done => browser.once('exit', done)); browser.kill('SIGTERM'); await exited;
  }
  await rm(work, {recursive:true, force:true});
}
